use crate::ir::*;

/// An [`InputMethod`] that holds reference to static map and state definitions generated by
/// the [`InputMethodFile::generate`] module.
///
/// [`InputMethodFile::generate`]: crate::ast::InputMethodFile::generate
#[derive(Debug)]
pub struct EmbeddableInputMethod<MapId: Id, MarkerId: Id, StateId: Id, VarId: Id> {
    /// The maps.
    pub maps: &'static [Map<MapId, MarkerId, StateId, VarId>],
    /// The states.
    pub states: &'static [State<MapId, MarkerId, StateId, VarId>],
    /// The initial state.
    pub initial_state: StateId,
}

impl<
    MapId: Id,
    MarkerId: Id + std::hash::Hash + 'static,
    StateId: Id,
    VarId: Id + std::hash::Hash + 'static,
> InputMethod for &'static EmbeddableInputMethod<MapId, MarkerId, StateId, VarId>
{
    type MapId = MapId;
    type MarkerId = MarkerId;
    type StateId = StateId;
    type VarId = VarId;

    fn get_map(
        &self,
        id: Self::MapId,
    ) -> Option<Map<Self::MapId, Self::MarkerId, Self::StateId, Self::VarId>> {
        self.maps.iter().find(|m| m.id == id).copied()
    }

    fn get_state(
        &self,
        id: Self::StateId,
    ) -> Option<State<Self::MapId, Self::MarkerId, Self::StateId, Self::VarId>> {
        self.states.iter().find(|s| s.id == id).copied()
    }

    fn initial_state(&self) -> Self::StateId {
        self.initial_state
    }
}

#[expect(missing_docs, reason = "doc hidden implementation details")]
pub mod helpers {
    pub use crate::{EmbeddableInputMethod, ir::*};

    pub use Operator::*;

    pub use Expr::Integer as int;
    pub use Expr::Op as op;
    pub use Expr::Variable as var;

    pub const fn text_rule<MarkerId: Id, StateId: Id, VarId: Id>(
        keyseq: &'static str,
        actions: &'static [Action<MarkerId, StateId, VarId>],
    ) -> TextRule<MarkerId, StateId, VarId> {
        TextRule { keyseq, actions }
    }
    pub const fn event_rule<MarkerId: Id, StateId: Id, VarId: Id>(
        events: &'static [KeyEvent],
        actions: &'static [Action<MarkerId, StateId, VarId>],
    ) -> EventRule<MarkerId, StateId, VarId> {
        EventRule { events, actions }
    }
    pub use KeyModifier::*;
    pub const fn key_event(modifiers: &'static [KeyModifier], base: &'static str) -> KeyEvent {
        KeyEvent { modifiers, base }
    }
}
